import { useEffect, useState } from "react";
import axios from "axios";

function Dashboard() {

  const [queues, setQueues] = useState([]);

  const fetchQueues = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/queue/all");
      setQueues(res.data);
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    fetchQueues();
  }, []);

  return (
    <div style={{ padding: "30px" }}>
      
      <h1>Queue List</h1>

      {queues.length === 0 ? (
        <p>No Queue Data</p>
      ) : (
        queues.map((q) => (
          <div
            key={q._id}
            style={{
              border: "1px solid black",
              padding: "10px",
              marginBottom: "10px"
            }}
          >
            <h3>Token: {q.tokenNumber}</h3>
            <p>Patient: {q.patientName}</p>
            <p>Status: {q.status}</p>
          </div>
        ))
      )}

    </div>
  );
}

export default Dashboard;
